function getFirstProvince() {
    for (var a in CITYS_DATA)
        return a;
    return ""
}

function getCitysByProvince(a) {
    var b = [],
        c;
    for (c in CITYS_DATA[a])
        b.push([c, c]);
    return b
}
var PROVINCES = [],
    key;
for (key in CITYS_DATA)
    PROVINCES.push([key, key]);
var CITYS = getCitysByProvince(getFirstProvince());
