Blockly.Blocks.pinyin_dict_create_with_items_insert = {
    init: function () {
        this.setColour(CategoryColors.Dictionary);
        this.appendDummyInput("").appendField(new Blockly.FieldLabel(Blockly.Msg.DICT_CREATE_WITH_INPUT_WITH), "TIP");
        this.itemCount_ = 3;
        this.updateShape_();
        this.setOutput(!0);
        this.setMutator(new Blockly.Mutator(["dict_create_with_item"]));
        this.setTooltip(Blockly.Msg.DICT_CREATE_WITH_ITEMS_INSERT_TOOLTIP)
    },
    mutationToDom: function () {
        var a = document.createElement("mutation");
        a.setAttribute("items", this.itemCount_);
        return a
    },
    domToMutation: function (a) {
        this.itemCount_ = parseInt(a.getAttribute("items"), 10);
        this.updateShape_()
    },
    decompose: function (a) {
        var b = a.newBlock("dict_create_with_container");
        b.initSvg();
        for (var c = b.getInput("STACK").connection, e = 0; e < this.itemCount_; e++) {
            var d = a.newBlock("dict_create_with_item");
            d.initSvg();
            c.connect(d.previousConnection);
            c = d.nextConnection
        }
        return b
    },
    compose: function (a) {
        a = a.getInputTargetBlock("STACK");
        for (var b = [], c = 0; a;)
            b[c] = a.valueConnection_,
                a = a.nextConnection && a.nextConnection.targetBlock(),
                c++;
        this.itemCount_ = c;
        this.updateShape_();
        for (c = 0; c < this.itemCount_; c++)
            b[c] && this.getInput("ADD" + c).connection.connect(b[c])
    },
    saveConnections: function (a) {
        a = a.getInputTargetBlock("STACK");
        for (var b = 0; a;) {
            var c = this.getInput("ADD" + b);
            a.valueConnection_ = c && c.connection.targetConnection;
            b++;
            a = a.nextConnection && a.nextConnection.targetBlock()
        }
    },
    updateShape_: function () {
        this.getInput("EMPTY") && this.removeInput("EMPTY");
        for (var a = [], b = 0; this.getInput("ADD" + b); b++)
            a.push(this.getFieldValue("KEY" + b)),
                this.removeInput("ADD" + b);
        if (0 == this.itemCount_)
            this.getField("TIP").setText(Blockly.Msg.DICT_CREATE_EMPTY_TITLE);
        else
            if (this.itemCount_ == 3 && a.length == 0) {
                for (this.getField("TIP").setText(Blockly.Msg.DICT_CREATE_WITH_INPUT_WITH),
                    b = 0; b < this.itemCount_; b++)
                    if (b == 0) {
                        this.appendValueInput("ADD" + b).setCheck(null).setAlign(Blockly.ALIGN_RIGHT).appendField(new Blockly.FieldTextInput("ni-hao-ya"), "KEY" + b).appendField(":")
                    }
                    else if (b == 1) {
                        this.appendValueInput("ADD" + b).setCheck(null).setAlign(Blockly.ALIGN_RIGHT).appendField(new Blockly.FieldTextInput("hao-de-ya"), "KEY" + b).appendField(":")
                    }
                    else {
                        this.appendValueInput("ADD" + b).setCheck(null).setAlign(Blockly.ALIGN_RIGHT).appendField(new Blockly.FieldTextInput("xiao-ai-ya"), "KEY" + b).appendField(":")
                    }
            }
            else {
                for (this.getField("TIP").setText(Blockly.Msg.DICT_CREATE_WITH_INPUT_WITH),
                    b = 0; b < this.itemCount_; b++)
                    this.appendValueInput("ADD" + b).setCheck(null).setAlign(Blockly.ALIGN_RIGHT).appendField(new Blockly.FieldTextInput(a.length > b ? a[b] : 0 == b ? "key_0" : "key_" + b), "KEY" + b).appendField(":")
            }
    },
    getVars: function () {
        return [this.getFieldValue("VAR")]
    },
    renameVar: function (a, b) {
        Blockly.Names.equals(a, this.getFieldValue("VAR")) && this.setTitleValue(b, "VAR")
    }
};

